/**
 * Solid Glass (`deeplethe/solid-glass`, MIT) as a sparse Theme v5 override over `base`
 * (`docs/decisions/0020-theme-v5.md`).
 */
import { defineTheme, type MaterialSpec } from "../../schema";
import { base } from "../nsh-gallery";

/** Smoky blur + specular top rim per appearance (`solidBlur` keeps `kind: "blur"`). */
function solidBlur(
  blur: number,
  saturate: number,
  minOpacity: number,
  mode: "light" | "dark",
): MaterialSpec {
  return {
    kind: "blur",
    blur,
    saturate,
    minOpacity,
    specular: mode === "light" ? "oklch(1 0 0 / 0.65)" : "oklch(1 0 0 / 0.14)",
  };
}

export const solidGlass = defineTheme({
  id: "solid-glass",
  label: "Solid Glass",
  extends: base,
  tokens: {
    radius: { control: 11, container: 14, modal: 20, curve: "continuous" },
    fixed: { scrim: "oklch(0 0 0 / 0.5)" },
    light: {
      background: "oklch(0.925 0.007 265)",
      card: "oklch(0.95776 0.00577 264.532)",
      popover: "oklch(0.98192 0.00286 264.542)",
