      surface: "oklch(1 0 0 / 0.55)",
      foreground: "oklch(0.16 0 0)",
      "muted-foreground": "oklch(0.47 0 0)",
      faint: "oklch(0.7 0 0)",
      primary: "oklch(0.2 0 0)",
      "primary-foreground": "oklch(0.985 0 0)",
      secondary: "oklch(1 0 0 / 0.55)",
      accent: "oklch(0.3 0.02 265 / 0.09)",
      brand: "oklch(0.49 0.12 165)",
      border: "oklch(0.3 0.02 265 / 0.13)",
      line: "var(--border)",
      input: "oklch(0.3 0.02 265 / 0.14)",
      ring: "oklch(0.2 0 0 / 0.5)",
      info: "oklch(0.56 0.16 248)",
      success: "oklch(0.58 0.15 152)",
      warning: "oklch(0.66 0.16 58)",
      destructive: "oklch(0.577 0.245 27.325)",
    },
    dark: {
      background: "oklch(0.16 0 0)",
      card: "oklch(0.23075 0 0)",
      popover: "oklch(0.21779 0 0)",
      muted: "oklch(1 0 0 / 0.07)",
      surface: "oklch(1 0 0 / 0.07)",
      foreground: "oklch(0.985 0 0)",
      "muted-foreground": "oklch(0.72 0 0)",
      faint: "oklch(0.52 0 0)",
      primary: "oklch(0.94 0 0)",
      "primary-foreground": "oklch(0.18 0 0)",
      secondary: "oklch(1 0 0 / 0.07)",
      accent: "oklch(1 0 0 / 0.08)",
      brand: "oklch(0.78 0.13 166)",
      border: "oklch(1 0 0 / 0.11)",
      line: "var(--border)",
      input: "oklch(1 0 0 / 0.08)",
      ring: "oklch(1 0 0 / 0.4)",
      info: "oklch(0.68 0.15 250)",
      success: "oklch(0.74 0.16 152)",
      warning: "oklch(0.77 0.15 62)",
      destructive: "oklch(0.704 0.191 22.216)",
    },
    tintAlpha: { light: 0.1, dark: 0.1 },
    tints: {
      light: { brand: "oklch(0.68 0.13 165 / 0.12)" },
      dark: { brand: "oklch(0.78 0.13 166 / 0.15)" },
    },
    chart: {
      light: [
        "oklch(0.7 0 0)",
        "oklch(0.54 0 0)",
        "oklch(0.44 0 0)",
