      md: "0 1px 2px oklch(0.25 0.03 265 / 0.06), 0 12px 32px -14px oklch(0.3 0.06 265 / 0.28)",
      lg: "inset 0 1px 0 oklch(1 0 0 / 0.9), inset 0 -1px 0 oklch(0.38 0.03 265 / 0.16), 0 24px 60px -18px oklch(0.3 0.06 265 / 0.28), 0 6px 16px -6px oklch(0.25 0.03 265 / 0.14)",
      xl: "inset 0 1px 0 oklch(1 0 0 / 0.9), inset 0 -1px 0 oklch(0.38 0.03 265 / 0.16), 0 24px 60px -18px oklch(0.3 0.06 265 / 0.28), 0 6px 16px -6px oklch(0.25 0.03 265 / 0.14)",
      inset: "inset 0 1px 1.5px oklch(0.3 0.06 265 / 0.14), inset 0 -1px 0 oklch(1 0 0 / 0.85)",
      edgeSurface: "inset 0 1px 0 oklch(1 0 0 / 0.9), inset 0 0 0 1px oklch(1 0 0 / 0.35)",
      edgeAccent:
        "inset 0 1px 0 oklch(1 0 0 / 0.3), inset 0 -1px 0 oklch(0 0 0 / 0.203), inset 0 0 0 1px oklch(1 0 0 / 0.07), 0 1px 2px oklch(0.25 0.03 265 / 0.06), 0 8px 18px -9px oklch(0.3 0.06 265 / 0.28)",
    },
    dark: {
      sm: "0 1px 2px oklch(0 0 0 / 0.1)",
      md: "0 1px 2px oklch(0 0 0 / 0.1), 0 12px 32px -14px oklch(0 0 0 / 0.6)",
      lg: "inset 0 1px 0 oklch(1 0 0 / 0.16), 0 24px 60px -18px oklch(0 0 0 / 0.6), 0 6px 16px -6px oklch(0 0 0 / 0.22)",
      xl: "inset 0 1px 0 oklch(1 0 0 / 0.16), 0 24px 60px -18px oklch(0 0 0 / 0.6), 0 6px 16px -6px oklch(0 0 0 / 0.22)",
      inset: "inset 0 1px 1.5px oklch(0 0 0 / 0.38), inset 0 -1px 0 oklch(1 0 0 / 0.09)",
      edgeSurface: "inset 0 1px 0 oklch(1 0 0 / 0.11), inset 0 0 0 1px oklch(1 0 0 / 0.04)",
      edgeAccent:
        "inset 0 1px 0 oklch(1 0 0), inset 0 -1px 0 oklch(0 0 0 / 0.099), inset 0 0 0 1px oklch(0 0 0 / 0.07), 0 1px 2px oklch(0 0 0 / 0.1), 0 8px 18px -9px oklch(0 0 0 / 0.6)",
    },
  },
  surfaces: {
    inset: {
      light: { background: "oklch(0.96648 0.00454 258.325)" },
      dark: { background: "oklch(0.27274 0 0)" },
    },
    channel: {
      light: { background: "oklch(0.96648 0.00454 258.325)" },
      dark: { background: "oklch(0.27274 0 0)" },
    },
    raised: {
      border: "line",
      light: { border: "line", borderTop: "line", borderBottom: "line" },
      dark: { border: "line", borderTop: "line", borderBottom: "line" },
    },
    plate: {
      border: "line",
      light: { background: "oklch(1 0 0 / 0.6)", border: "line" },
      dark: { background: "oklch(1 0 0 / 0.06)", border: "line" },
    },
    overlay: {
      effect: { kind: "specular-rim", intensity: 0.35 },
      light: {
        background: { color: "popover", alpha: 0.8 },
        border: "oklch(0.38 0.03 265 / 0.22)",
        material: solidBlur(18, 1.5, 0.72, "light"),
      },
      dark: {
        background: { color: "popover", alpha: 0.82 },
        border: "oklch(1 0 0 / 0.13)",
        material: solidBlur(18, 1.4, 0.72, "dark"),
      },
    },
    modal: {
      effect: { kind: "specular-rim", intensity: 0.25 },
      light: {
        background: { color: "card", alpha: 0.86 },
        material: solidBlur(22, 1.35, 0.8, "light"),
      },
      dark: {
        background: { color: "card", alpha: 0.88 },
        material: solidBlur(22, 1.3, 0.8, "dark"),
      },
    },
    inverse: {
      foreground: "foreground",
      effect: { kind: "specular-rim", intensity: 0.3 },
      light: {
        background: { color: "popover", alpha: 0.82 },
        border: "oklch(0.38 0.03 265 / 0.22)",
        material: solidBlur(16, 1.4, 0.75, "light"),
      },
      dark: {
        background: { color: "popover", alpha: 0.84 },
        border: "oklch(1 0 0 / 0.13)",
        material: solidBlur(16, 1.3, 0.75, "dark"),
      },
    },
    glass: {
      background: "surface",
      border: "line",
      material: { kind: "blur", blur: 14, saturate: 1.8, minOpacity: 0.55 },
      effect: { kind: "specular-rim", intensity: 0.4 },
      light: { background: "surface", backdropFilter: "blur(14px) saturate(180%)" },
      // Dark `surface` is white at 0.07. The blur floor is 0.55, so this face uses the
      // dark card at 0.72 instead of raising the shared `surface` token.
      dark: { background: { color: "card", alpha: 0.72 }, backdropFilter: "blur(14px)" },
    },
    accent: {
      light: {
        background: { color: "primary", alpha: 0.88 },
        border: "oklch(0.2 0 0 / 0.685)",
        borderBottom: "oklch(0.2 0 0 / 0.685)",
      },
      dark: {
        background: { color: "primary", alpha: 0.86 },
        border: "oklch(0.967 0 0 / 0.667)",
        borderBottom: "oklch(0.967 0 0 / 0.667)",
      },
    },
    fill: {
      light: {
        background: { color: "primary", alpha: 0.88 },
        gradient: null,
        border: "oklch(0.2 0 0 / 0.685)",
      },
      dark: {
        background: { color: "primary", alpha: 0.86 },
        gradient: null,
        border: "oklch(0.967 0 0 / 0.667)",
      },
    },
  },
  feedback: {
    hover: {
      fill: { light: "oklch(0.3 0.02 265 / 0.1)", dark: "oklch(1 0 0 / 0.08)" },
      surface: {
        light: {
          background: "oklch(0.3 0.02 265 / 0.1)",
          border: "line",
          borderTop: "line",
          borderBottom: "line",
        },
        dark: {
          background: "oklch(1 0 0 / 0.08)",
          border: "line",
          borderTop: "line",
          borderBottom: "line",
